def solve(n, k, a):
    if k == 2:
        # Check if there is at least one even number
        for x in a:
            if x % 2 == 0:
                return 0
        return n  # All numbers are odd, need to make one even

    elif k == 3:
        # Check if there is at least one number divisible by 3
        for x in a:
            if x % 3 == 0:
                return 0
        # Find the minimum number of operations to make a number divisible by 3
        min_ops = float('inf')
        for x in a:
            if x % 3 == 1:
                min_ops = min(min_ops, 2)
            elif x % 3 == 2:
                min_ops = min(min_ops, 1)
        return min_ops

    elif k == 4:
        # Check if there is at least one number divisible by 4
        for x in a:
            if x % 4 == 0:
                return 0
        # Check if there are at least two even numbers
        even_count = sum(1 for x in a if x % 2 == 0)
        if even_count >= 2:
            return 0
        # Find the minimum number of operations to make a number divisible by 4
        min_ops = float('inf')
        for x in a:
            if x % 4 == 1:
                min_ops = min(min_ops, 3)
            elif x % 4 == 2:
                min_ops = min(min_ops, 2)
            elif x % 4 == 3:
                min_ops = min(min_ops, 1)
        return min_ops

    elif k == 5:
        # Check if there is at least one number divisible by 5
        for x in a:
            if x % 5 == 0:
                return 0
        # Find the minimum number of operations to make a number divisible by 5
        min_ops = float('inf')
        for x in a:
            if x % 5 == 1:
                min_ops = min(min_ops, 4)
            elif x % 5 == 2:
                min_ops = min(min_ops, 3)
            elif x % 5 == 3:
                min_ops = min(min_ops, 2)
            elif x % 5 == 4:
                min_ops = min(min_ops, 1)
        return min_ops

